insert into public.sq_lorekeeper (term_id, is_active, grade_level, passage, question, choice_a, choice_b, choice_c, choice_d, correct_choice) values
  (1, true, 6, NULL, 'A dog and a wolf belonging to the same genus (Canis) but different species shows that they are', 'Identical species with no differences', 'Closely related but genetically distinct', 'In completely different kingdoms', 'Not related in any way', 'b'),
  (1, true, 6, NULL, 'Which of these best explains why classifying an organism correctly (kingdom through species) matters for scientific research?', 'It allows scientists worldwide to identify and study the exact same organism without confusion', 'It has no practical benefit to research', 'It only matters for organizing museum displays', 'Classification changes randomly and has no consistent rules', 'a'),
  (1, true, 6, NULL, 'Coral reefs are considered biodiversity hotspots mainly because they', 'Support an enormous variety of marine species in a relatively small area', 'Have almost no living organisms', 'Only support one single species', 'Are found only in freshwater lakes', 'a'),
  (1, true, 6, NULL, 'Which of these is the best example of a strategy that addresses overfishing as a threat to biodiversity?', 'Establishing marine protected areas with fishing restrictions', 'Removing all fishing regulations entirely', 'Encouraging unlimited fishing in all areas', 'Ignoring fish population data', 'a'),
  (1, true, 6, NULL, 'Which of these best explains the concept of a keystone species in an ecosystem?', 'A species that has an unusually large effect on its ecosystem relative to its population size', 'A species that has no effect on its ecosystem', 'The most common species in every ecosystem', 'A species found only in zoos', 'a'),
  (1, true, 6, NULL, 'Which of these best describes the effect of removing a keystone species, like a sea otter, from its ecosystem?', 'It can cause major imbalances throughout the food web', 'It has no effect on the rest of the ecosystem', 'It always improves the ecosystem', 'Other species become completely unaffected', 'a'),
  (1, true, 6, NULL, 'A subduction zone forms when', 'One tectonic plate is forced beneath another plate', 'Two plates move apart from each other', 'Plates never interact with one another', 'A volcano stops erupting permanently', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why earthquakes are common along transform boundaries, like the San Andreas Fault?', 'Plates sliding past each other build up stress that is suddenly released as seismic energy', 'Transform boundaries never produce earthquakes', 'Plates at transform boundaries always move smoothly with no friction', 'Earthquakes only happen at convergent boundaries', 'a'),
  (1, true, 6, NULL, 'Seismic waves are best described as', 'The energy waves released during an earthquake that travel through the Earth', 'A type of ocean current', 'A form of volcanic gas', 'A measurement of rainfall', 'a'),
  (1, true, 6, NULL, 'Which of these volcanic products is a mixture of hot gas, ash, and rock fragments that flows rapidly down a volcano''s slope?', 'Pyroclastic flow', 'Lava dome only', 'Volcanic bomb only', 'Tephra only', 'a'),
  (1, true, 6, NULL, 'Which of these best describes lahar, a hazard commonly associated with Philippine volcanoes like Mount Pinatubo?', 'A mudflow of volcanic debris mixed with water, often triggered by heavy rain', 'A type of earthquake', 'A calm, slow-moving lava flow only', 'A form of clean drinking water', 'a'),
  (1, true, 6, NULL, 'Weathering that occurs when rocks are physically broken apart without changing their chemical composition is called', 'Mechanical (physical) weathering', 'Chemical weathering', 'Biological deposition', 'Volcanic weathering only', 'a'),
  (1, true, 6, NULL, 'Weathering that occurs when a rock''s minerals are altered by chemical reactions, such as rusting, is called', 'Mechanical weathering', 'Chemical weathering', 'Erosion only', 'Deposition only', 'b'),
  (1, true, 6, NULL, 'Which of these best explains why coastal areas often experience significant erosion?', 'Waves and currents continuously wear away and move sediment along the shoreline', 'Coastal areas never experience any water movement', 'Erosion only occurs in deserts', 'Ocean water has no effect on rocks or sand', 'a'),
  (1, true, 6, NULL, 'Which of these best describes the relationship between voltage, current, and resistance in a simple electrical circuit?', 'They are all interconnected and affect how much current flows through the circuit', 'They have no relationship with each other', 'Voltage always stays at zero in a working circuit', 'Resistance has no effect on current', 'a'),
  (1, true, 6, NULL, 'A switch in an electrical circuit is used to', 'Open or close the circuit, controlling whether current flows', 'Increase the voltage permanently', 'Convert electricity into light only', 'Store electrical energy forever', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why household appliances are typically wired in parallel circuits rather than series circuits?', 'So each appliance can operate independently without depending on the others', 'So all appliances turn off if one stops working', 'Parallel circuits provide no benefit over series circuits', 'Series circuits are always safer for homes', 'a'),
  (1, true, 6, NULL, 'A generator converts what form of energy into electrical energy?', 'Mechanical energy', 'Chemical energy only', 'Sound energy only', 'No energy conversion occurs', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why understanding electrical safety, like avoiding overloaded outlets, is important?', 'Overloaded circuits can overheat and cause fires or damage', 'Electrical safety has no real-world importance', 'Overloading outlets always makes appliances work better', 'Circuits can never be overloaded', 'a'),
  (1, true, 6, NULL, 'Which of these best describes how puberty timing can vary between individuals?', 'It is completely identical for every single person with no variation', 'It can begin at different ages and progress at different rates for different people', 'It never varies based on genetics or health', 'It always starts at exactly the same age for everyone', 'b'),
  (1, true, 6, NULL, 'Which of these best describes a healthy way to cope with the emotional changes of adolescence?', 'Talking to trusted adults, friends, or counselors about feelings', 'Never discussing feelings with anyone', 'Ignoring all emotions completely', 'Avoiding all forms of communication', 'a'),
  (1, true, 6, NULL, 'Which of these best describes why hygiene habits often become more important to teach and practice during adolescence?', 'The body undergoes changes that make regular hygiene routines more important for health', 'Hygiene has no connection to physical development', 'Hygiene habits should stop during this stage', 'The body needs less care during this stage', 'a'),
  (1, true, 6, 'The ancient Chinese civilization made many lasting contributions, including papermaking, the compass, and gunpowder. These inventions eventually spread along trade routes to other parts of the world, influencing global history.', 'According to the passage, how did Chinese inventions influence the rest of the world?', 'They spread through trade routes to other regions', 'They remained completely isolated within China forever', 'They had no influence outside of China', 'They were invented by other civilizations first', 'a'),
  (1, true, 6, NULL, 'Which of these was a major invention credited to ancient China?', 'Papermaking', 'The printing press in Europe', 'The pyramids', 'The wheel, invented first in China', 'a'),
  (1, true, 6, NULL, 'The Silk Road was significant in ancient Asian history because it', 'Connected China to other regions for trade of goods and ideas', 'Was a road used only for foot races', 'Had no economic or cultural impact', 'Only connected two cities within Japan', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why ancient civilizations like Mesopotamia developed near rivers?', 'Rivers provided water for agriculture, transportation, and daily life', 'Rivers had no benefit to early civilizations', 'Ancient people avoided settling near water sources', 'Rivers made farming impossible', 'a'),
  (1, true, 6, NULL, 'The Code of Hammurabi, from ancient Mesopotamia, is significant because it', 'Was one of the earliest known written sets of laws', 'Was a type of ancient currency', 'Was a religious text with no legal content', 'Had no influence on later legal systems', 'a'),
  (1, true, 6, NULL, 'During the American colonial period, which language became the primary medium of instruction in Philippine public schools?', 'Spanish', 'English', 'Mandarin', 'Latin', 'b'),
  (1, true, 6, NULL, 'Which of these best describes the goal of the Commonwealth government established in the Philippines in 1935?', 'To transition the Philippines toward eventual full self-governance and independence', 'To make the Philippines a permanent American territory forever', 'To return the Philippines to Spanish rule', 'To immediately grant full independence with no transition period', 'a'),
  (1, true, 6, NULL, 'The Bataan Death March during World War II is remembered as', 'A tragic forced march of prisoners of war under harsh conditions', 'A peaceful celebration', 'A trade agreement between countries', 'A modern infrastructure project', 'a'),
  (1, true, 6, NULL, 'Which of these best describes the significance of Philippine independence being declared on June 12, 1898, versus recognized on July 4, 1946?', 'June 12, 1898 marks the declaration from Spain, while July 4, 1946 marks recognized independence from the United States', 'Both dates refer to the exact same event with no distinction', 'Neither date has historical significance', 'July 4, 1946 marks independence from Spain', 'a'),
  (1, true, 6, NULL, 'Which of these Philippine presidents served during the Martial Law era (1972–1986)?', 'Ferdinand Marcos', 'Manuel Quezon', 'Emilio Aguinaldo', 'Corazon Aquino only, before Martial Law began', 'a'),
  (1, true, 6, NULL, 'Corazon Aquino became president of the Philippines following which historic event?', 'The People Power Revolution of 1986', 'World War II', 'The Spanish-American War', 'The declaration of the Commonwealth', 'a'),
  (1, true, 6, NULL, 'Which of these best explains the long-term significance of the People Power Revolution for Philippine democracy?', 'It demonstrated that peaceful mass action could restore democratic governance', 'It permanently ended all future elections', 'It had no lasting political impact', 'It led to the country becoming a colony again', 'a'),
  (1, true, 6, NULL, 'Which of these best explains the economic concept of "opportunity cost"?', 'The value of the next best alternative given up when making a choice', 'The total amount of money a business earns', 'A type of tax collected by the government', 'The exact price of a single product', 'a'),
  (1, true, 6, NULL, 'Inflation refers to', 'A general increase in prices and decrease in the purchasing power of money over time', 'A decrease in all prices permanently', 'A type of government law', 'A method of tax collection only', 'a'),
  (1, true, 6, NULL, 'Which of these is an example of a direct tax paid by individuals based on their income?', 'Income tax', 'Value-added tax on goods', 'A cooperative''s shared profit', 'A bank''s interest rate', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why a national budget needs to balance government spending and revenue?', 'Spending far more than is collected can lead to debt and economic problems', 'Balancing a budget has no economic consequences', 'Governments should always spend without limit', 'Revenue collection is unnecessary for governments', 'a'),
  (1, true, 6, NULL, 'Which of these best describes the role of the Bangko Sentral ng Pilipinas (BSP)?', 'It serves as the Philippines'' central bank, managing currency and monetary policy', 'It is a private company selling consumer goods', 'It has no role in the Philippine economy', 'It is a branch of the judicial system', 'a'),
  (1, true, 6, NULL, 'Which of these best describes how the legislative branch of Philippine government is structured?', 'A bicameral Congress made up of the Senate and the House of Representatives', 'A single unelected council', 'It has no formal structure at all', 'It consists only of the President', 'a'),
  (1, true, 6, NULL, 'Which of these best describes the role of the Supreme Court in the Philippine judicial branch?', 'It is the highest court, responsible for interpreting the constitution and settling major legal disputes', 'It creates all new laws', 'It is part of the executive branch', 'It has no authority over legal matters', 'a'),
  (1, true, 6, NULL, 'Which of these best describes the role of a barangay captain within an LGU?', 'Leading the smallest local government unit and addressing community concerns', 'Serving as the head of the national government', 'Having no responsibilities within the community', 'Serving only as a ceremonial title with no duties', 'a'),
  (1, true, 6, NULL, 'If the President vetoes a bill passed by Congress, what can Congress do next?', 'Attempt to override the veto with a sufficient majority vote', 'The bill is permanently dead with no further options', 'The bill automatically becomes law regardless', 'Congress has no further options at all', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why checks and balances exist among the three branches of Philippine government?', 'To prevent any one branch from having too much unchecked power', 'To make all three branches identical in function', 'Checks and balances serve no real purpose', 'To eliminate the need for a judicial branch', 'a'),
  (1, true, 6, NULL, 'Which of these best describes how the UN Security Council differs from the UN General Assembly?', 'The Security Council has more power over peace and security matters, including permanent members with veto power', 'They are exactly the same body with no differences', 'The General Assembly has more power over international security than the Security Council', 'Neither body has any real authority', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why the WHO played an important role during global health crises like pandemics?', 'It coordinates international responses and shares critical health information among countries', 'It has no role in coordinating health responses', 'It only focuses on economic issues', 'It replaces national health departments entirely', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why UNICEF focuses specifically on children''s welfare worldwide?', 'Children are especially vulnerable and need dedicated advocacy for their rights and needs', 'Children''s issues have no global significance', 'UNICEF only operates within one single country', 'Children''s welfare is identical to adult welfare with no distinction needed', 'a'),
  (1, true, 6, NULL, 'Which of these is a key function the WTO performs for its member countries?', 'Resolving trade disputes and setting rules for international commerce', 'Managing global healthcare systems', 'Overseeing children''s education programs', 'Controlling national military forces', 'a'),
  (1, true, 6, NULL, 'In literature, when a character''s outward actions conflict with the reader''s understanding of their true feelings, this may be an example of', 'Dramatic irony', 'Rhyme scheme', 'Alliteration', 'Meter', 'a'),
  (1, true, 6, NULL, 'In literature, when the audience knows something a character does not, this is called', 'Dramatic irony', 'Situational irony', 'Verbal irony', 'Personification', 'a'),
  (1, true, 6, NULL, 'When a character says the opposite of what they truly mean, often sarcastically, this is called', 'Dramatic irony', 'Verbal irony', 'Situational irony', 'Foreshadowing', 'b'),
  (1, true, 6, NULL, 'A story''s climax refers to', 'The turning point or moment of greatest tension in the plot', 'The introduction of characters at the very beginning', 'The setting description only', 'The title of the story', 'a'),
  (1, true, 6, NULL, 'The resolution of a story refers to', 'The part where the main conflict is settled and loose ends are tied up', 'The very first paragraph of the story', 'A character''s physical description', 'The book''s table of contents', 'a'),
  (1, true, 6, NULL, 'Which of these best explains the literary technique of an unreliable narrator?', 'A narrator whose credibility is compromised, making readers question the accuracy of their account', 'A narrator who is always completely truthful and objective', 'A narrator who never appears in the story', 'A term with no real meaning in literature', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why writers use a counterargument in a persuasive essay?', 'It shows the writer has considered opposing views, making their argument more credible', 'It weakens the writer''s argument for no reason', 'It is required to have no connection to the main claim', 'It replaces the need for evidence', 'a'),
  (1, true, 6, NULL, 'Which of these best describes why citing sources properly strengthens an argumentative essay?', 'It shows the writer''s claims are backed by credible research, building trust with the reader', 'Citing sources weakens the essay', 'Sources are never necessary in formal writing', 'Citations have no effect on credibility', 'a'),
  (1, true, 6, NULL, 'Which of these is the best example of a reliable, credible source for academic research?', 'A peer-reviewed scientific journal article', 'An anonymous social media post with no evidence', 'A blog with no author or citations', 'A rumor shared by a friend', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why paraphrasing still requires citing the original source?', 'The idea originally came from someone else, even if the wording is changed', 'Paraphrased ideas never need credit', 'Paraphrasing removes all obligation to cite sources', 'Only direct quotes require citation, never paraphrases', 'a'),
  (1, true, 6, NULL, 'Which sentence correctly reports a question using reported speech?', 'He asked if she was coming to the party.', 'He asked, "Is she coming to the party?"', 'He asked if is she coming to the party.', 'He asked she is coming to the party.', 'a'),
  (1, true, 6, NULL, 'Which sentence correctly uses a non-restrictive relative clause set off by commas?', 'My brother, who lives in Cebu, is visiting next week.', 'My brother who lives in Cebu is visiting next week, is coming.', 'My brother, who, lives in Cebu is visiting next week.', 'My brother who, lives in Cebu, is visiting, next week.', 'a'),
  (1, true, 6, NULL, 'Which sentence correctly uses a gerund phrase as the subject of the sentence?', 'Reading novels every night helps improve vocabulary.', 'To reading novels every night helps improve vocabulary.', 'Read novels every night helps improve vocabulary.', 'Reads novels every night helps improve vocabulary.', 'a'),
  (1, true, 6, NULL, 'Which sentence correctly uses an infinitive phrase to express purpose?', 'She saved money to buy a new bicycle.', 'She saved money for to buy a new bicycle.', 'She saved money buying a new bicycle to.', 'She saved money to buying a new bicycle.', 'a'),
  (1, true, 6, NULL, 'The idiomatic expression "once in a blue moon" means', 'Something that happens very rarely', 'Something that happens every single day', 'A type of moon phase only', 'Something that never happens at all', 'a'),
  (1, true, 6, NULL, 'The idiomatic expression "the ball is in your court" means', 'It is now your turn or responsibility to make a decision or take action', 'A literal sports term with no figurative meaning', 'Someone has lost a game', 'A person should stop playing sports', 'a'),
  (1, true, 6, NULL, 'Which pair of words are near-synonyms with a subtle difference: "assertive" and "aggressive"?', 'Assertive suggests confident and respectful communication, while aggressive suggests forceful or hostile behavior', 'They mean exactly the same thing with no distinction', 'Assertive means passive, and aggressive means calm', 'They are unrelated words with no similarity', 'a'),
  (1, true, 6, NULL, 'Ang uring dula na ginagamitan ng kanta at sayaw upang ilahad ang kwento ay tinatawag na', 'Musikal na dula (musical)', 'Tuluyan', 'Talumpati', 'Sanaysay', 'a'),
  (1, true, 6, NULL, 'Ang dulang trahedya ay karaniwang nagtatapos sa', 'Masayang wakas', 'Malungkot o madugong wakas', 'Walang wakas', 'Katatawanan lamang', 'b'),
  (1, true, 6, NULL, 'Ang dulang komedya ay karaniwang naglalayong', 'Magpatawa o magbigay-aliw sa manonood', 'Magbigay ng malungkot na damdamin', 'Magturo lamang ng agham', 'Walang layunin', 'a'),
  (1, true, 6, NULL, 'Sa pagsusuri ng isang talambuhay, mahalagang tukuyin kung ang manunulat ay', 'May sapat na ebidensya at hindi kinikilingan sa paglalahad ng katotohanan', 'Basta magsulat lamang nang walang batayan', 'Walang pakialam sa katumpakan ng impormasyon', 'Palaging sumusulat ng kathang-isip lamang', 'a'),
  (1, true, 6, NULL, 'Bakit mas madalas isulat ang talambuhay ng mga taong tanyag o may malaking kontribusyon sa lipunan?', 'Upang maipamana ang kanilang kwento at maging inspirasyon sa iba', 'Dahil wala silang ginawang mahalaga', 'Dahil bawal isulat ang buhay ng ordinaryong tao', 'Walang partikular na dahilan', 'a'),
  (1, true, 6, NULL, 'Sa induktibong pangangatwiran, ang konklusyon ay', 'Nagmumula sa pangkalahatang alituntunin', 'Nabubuo batay sa mga tiyak na obserbasyon o ebidensya', 'Palaging mali', 'Walang kaugnayan sa ebidensya', 'b'),
  (1, true, 6, NULL, 'Bakit mahalagang suriin ang punto de bista ng manunulat kapag bumabasa ng isang teksto?', 'Upang maunawaan kung paano ito nakaaapekto sa paraan ng pagkakasulat at nilalaman ng akda', 'Walang epekto ang punto de bista sa isang akda', 'Ito ay hindi kailanman nagbabago sa akda', 'Hindi ito mahalagang tukuyin', 'a'),
  (1, true, 6, NULL, 'Alin sa mga sumusunod ang halimbawa ng mapanuring pagbabasa?', 'Pagsusuri ng katotohanan, ebidensya, at hilig ng isang teksto bago ito paniwalaan nang lubusan', 'Basta pagbabasa nang walang pag-iisip', 'Paniniwala kaagad sa lahat ng nababasa', 'Pagbabalewala sa nilalaman ng teksto', 'a'),
  (1, true, 6, NULL, 'Ang aspektong perpektibo, imperpektibo, at kontemplatibo ng pandiwa ay tumutukoy sa', 'Kasarian ng pangngalan', 'Panahon o katayuan ng isang kilos kung ito ay natapos na, kasalukuyan, o balak pa lamang', 'Bilang ng pangngalan', 'Uri ng tayutay', 'b'),
  (1, true, 6, NULL, 'Alin sa mga sumusunod ang pandiwang perpektibo ng salitang-ugat na "basa"?', 'Nagbasa', 'Nagbabasa', 'Magbabasa', 'Basahin', 'a'),
  (1, true, 6, NULL, 'Alin sa mga sumusunod ang pandiwang imperpektibo ng salitang-ugat na "basa"?', 'Nagbasa', 'Nagbabasa', 'Magbabasa', 'Basahin', 'b'),
  (1, true, 6, NULL, 'Alin sa mga sumusunod ang pandiwang kontemplatibo ng salitang-ugat na "basa"?', 'Nagbasa', 'Nagbabasa', 'Magbabasa', 'Basahin', 'c');